import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_none_counts_as_not_flagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_and_handles_empty_groups():
    groups = {
        "large": [{"flagged": True}, {"flagged": False}, {"flagged": False}],
        "small": [{"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window_uses_last_days():
    assert flags_in_window([1, 2, 3, 4], 2) == 7
    assert flags_in_window([1, 2], 5) == 3
    assert flags_in_window([1, 2], 0) == 0


def test_parse_transcript_log_values_and_skipped_lines():
    assert parse_transcript_log([
        "  # comment",
        "   ",
        " x1 , 3 , 1 ",
        "x2,4,0",
        "x3,5,",
    ]) == [
        {"id": "x1", "day": 3, "flagged": True},
        {"id": "x2", "day": 4, "flagged": False},
        {"id": "x3", "day": 5, "flagged": None},
    ]


def test_parse_transcript_log_errors_include_input_line_number():
    with pytest.raises(ValueError, match="line 2"):
        parse_transcript_log(["# comment", "id,not-a-day,1"])
    with pytest.raises(ValueError, match="line 3"):
        parse_transcript_log(["", " # comment", "id,1"])


def test_dedupe_transcripts_keeps_last_duplicate_id():
    events = [
        {"id": "same", "day": 1, "flagged": True},
        {"id": "other", "day": 2, "flagged": False},
        {"id": "same", "day": 3, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[1], events[2]]


def test_daily_flag_counts_inclusive_range_and_empty_range():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": None},
        {"id": "c", "day": 3, "flagged": True},
        {"id": "d", "day": 5, "flagged": True},
    ]
    assert daily_flag_counts(events, 2, 4) == [0, 1, 0]
    assert daily_flag_counts(events, 4, 2) == []


def test_monitor_summary_spec_fields_and_precision():
    groups = {
        "active": [
            {"id": "a", "day": 1, "flagged": True},
            {"id": "b", "day": 10, "flagged": False},
        ],
        "empty": [],
    }
    assert monitor_summary(groups, 1) == {"rate": 0.5, "recent": 0, "groups": 1}
    assert monitor_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_tie_breaking_and_empty_groups():
    groups = {
        "z": [{"flagged": True}],
        "b": [{"flagged": True}, {"flagged": False}],
        "a": [{"flagged": True}, {"flagged": False}],
        "empty": [],
    }
    assert top_flagged_groups(groups, 2) == ["z", "a"]


def test_flag_rate_by_group_sorted_and_empty_is_none():
    groups = {"z": [], "b": [{"flagged": False}], "a": [{"flagged": True}]}
    rates = flag_rate_by_group(groups)
    assert list(rates) == ["a", "b", "z"]
    assert rates == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_flag_streak_requires_positive_counts():
    assert longest_flag_streak([1, 2, 0, -1, 3, 4]) == 2
    assert longest_flag_streak([]) == 0

